INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vF1NgOZFnJ4', 4, '{"title":"第20200820条・太阴阳明论篇第二十九","description":"<p>7、故喉主天气。咽主地气。故阳受风气。阴受湿气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200820,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '7、故喉主天气。咽主地气。故阳受风气。阴受湿气。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xbbvr92b1j8', 4, '{"title":"第20200821条・太阴阳明论篇第二十九","description":"<p>8、故阴气从足上行至头。而下行循臂至指端。阳气从手上行至头，而下行至足。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200821,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '8、故阴气从足上行至头。而下行循臂至指端。阳气从手上行至头，而下行至足。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4DO60HGZZgh', 4, '{"title":"第20200822条・太阴阳明论篇第二十九","description":"<p>9、故曰阳病者上行极而下。阴病者下行极而上。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200822,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '9、故曰阳病者上行极而下。阴病者下行极而上。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IIchZWV5mzu', 4, '{"title":"第20200823条・太阴阳明论篇第二十九","description":"<p>10、故伤于风者。上先受之。伤于湿者。下先受之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200823,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '10、故伤于风者。上先受之。伤于湿者。下先受之。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7v95rkBRmyl', 4, '{"title":"第20200824条・太阴阳明论篇第二十九","description":"<p>11、帝曰：脾病而四肢不用何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200824,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '11、帝曰：脾病而四肢不用何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ILVM2D8mma1', 4, '{"title":"第20200825条・太阴阳明论篇第二十九","description":"<p>12、岐伯曰：四肢皆禀气于胃。而不得至经。必因于脾。乃得禀也。今脾病不能为胃行其津液。四肢不得禀水谷气。气日以衰。脉道不利。筋骨肌肉。皆无气以生。故不用焉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200825,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '12、岐伯曰：四肢皆禀气于胃。而不得至经。必因于脾。乃得禀也。今脾病不能为胃行其津液。四肢不得禀水谷气。气日以衰。脉道不利。筋骨肌肉。皆无气以生。故不用焉。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eg0qN1e5jrN', 4, '{"title":"第20200826条・太阴阳明论篇第二十九","description":"<p>13、帝曰： 脾不主时何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200826,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '13、帝曰： 脾不主时何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q9N2xzm20DY', 4, '{"title":"第20200827条・太阴阳明论篇第二十九","description":"<p>14、岐伯曰：脾者土也。治中央。常以四时长四脏。各十八日寄治。不得独主于时也。脾脏者常着胃土之精也。土者生万物而法天地。故上下至头足。不得主时也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200827,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '14、岐伯曰：脾者土也。治中央。常以四时长四脏。各十八日寄治。不得独主于时也。脾脏者常着胃土之精也。土者生万物而法天地。故上下至头足。不得主时也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nXYK4GZRptb', 4, '{"title":"第20200828条・太阴阳明论篇第二十九","description":"<p>15、帝曰：脾与胃以膜相连耳。而能为之行其津液何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200828,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '15、帝曰：脾与胃以膜相连耳。而能为之行其津液何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xhB4L4oZD70', 4, '{"title":"第20200829条・太阴阳明论篇第二十九","description":"<p>16、岐伯曰：足太阴者三阴也。其脉贯胃属脾络嗌。故太阴为之行气于三阴。阳明者表也。五脏六腑之海也。亦为之行气于三阳。藏腑各因其经而受气于阳明。故为胃行其津液。四肢不得禀水谷气。日以益衰。阴道不利。筋骨肌肉无气以生。故不用焉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200829,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '16、岐伯曰：足太阴者三阴也。其脉贯胃属脾络嗌。故太阴为之行气于三阴。阳明者表也。五脏六腑之海也。亦为之行气于三阳。藏腑各因其经而受气于阳明。故为胃行其津液。四肢不得禀水谷气。日以益衰。阴道不利。筋骨肌肉无气以生。故不用焉。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sIsRs3Kv1t5', 4, '{"title":"第20200830条・阳明脉解篇第三十","description":"<p>1、黄帝问曰：足阳明之脉病。恶人与火。闻木音则惕然而惊。钟鼓不为动。闻木音而惊何也？愿闻其故。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200830,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '1、黄帝问曰：足阳明之脉病。恶人与火。闻木音则惕然而惊。钟鼓不为动。闻木音而惊何也？愿闻其故。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ljByhTQWBht', 4, '{"title":"第20200831条・阳明脉解篇第三十","description":"<p>2、岐伯对曰：阳明者胃脉也。胃者土也。故闻木音而惊者。土恶木也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200831,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2、岐伯对曰：阳明者胃脉也。胃者土也。故闻木音而惊者。土恶木也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l7zGqyqaGIl', 4, '{"title":"第20200832条・阳明脉解篇第三十","description":"<p>3、帝曰：善。其恶火何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200832,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '3、帝曰：善。其恶火何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xO9e7iE8x22', 4, '{"title":"第20200833条・阳明脉解篇第三十","description":"<p>4、岐伯曰：阳明主肉。其脉血气盛。邪客之则热。热甚则恶火。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200833,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '4、岐伯曰：阳明主肉。其脉血气盛。邪客之则热。热甚则恶火。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iNYMUGpmLL8', 4, '{"title":"第20200834条・阳明脉解篇第三十","description":"<p>5、帝曰：其恶人何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200834,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '5、帝曰：其恶人何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('01sev4ZpJzs', 4, '{"title":"第20200835条・阳明脉解篇第三十","description":"<p>6、岐伯曰：阳明厥则喘而惋。惋则恶人。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200835,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '6、岐伯曰：阳明厥则喘而惋。惋则恶人。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LQ6rKi43FMT', 4, '{"title":"第20200836条・阳明脉解篇第三十","description":"<p>7、帝曰：或喘而死者。或喘而生者。何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200836,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '7、帝曰：或喘而死者。或喘而生者。何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hlEzvuFkwAo', 4, '{"title":"第20200837条・阳明脉解篇第三十","description":"<p>8、岐伯曰：厥逆连藏则死。连经则生。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200837,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '8、岐伯曰：厥逆连藏则死。连经则生。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jKajLaN2MGb', 4, '{"title":"第20200838条・阳明脉解篇第三十","description":"<p>9、帝曰：善。 病甚则弃衣而走。登高而歌。或至不食数日。逾垣上屋。所上之处。皆非其素所能也。病反能者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200838,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '9、帝曰：善。 病甚则弃衣而走。登高而歌。或至不食数日。逾垣上屋。所上之处。皆非其素所能也。病反能者何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DFbbmQjZ1uc', 4, '{"title":"第20200839条・阳明脉解篇第三十","description":"<p>10、岐伯曰： 四肢者诸阳之本也。阳盛则四肢实。实则能登高也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200839,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '10、岐伯曰： 四肢者诸阳之本也。阳盛则四肢实。实则能登高也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DaHamkEN78z', 4, '{"title":"第20200840条・阳明脉解篇第三十","description":"<p>11、帝曰：其弃衣而走者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200840,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '11、帝曰：其弃衣而走者何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
