INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J6pEbS0ewua', 4, '{"title":"第20200842条・阳明脉解篇第三十","description":"<p>13、帝曰：其妄言骂詈不避亲疏而歌者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200842,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '13、帝曰：其妄言骂詈不避亲疏而歌者何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dJdgDc0GNM7', 4, '{"title":"第20200843条・阳明脉解篇第三十","description":"<p>14、岐伯曰：阳盛则使人妄言骂詈不避亲疏而不欲食。不欲食故妄走也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200843,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '14、岐伯曰：阳盛则使人妄言骂詈不避亲疏而不欲食。不欲食故妄走也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ybMBOwopv7Y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JU5F0j9bNtB', 4, '{"title":"第20200844条・热论篇第三十一","description":"<p>1、黄帝问曰：今夫热病者。皆伤寒之类也。或愈或死。其死皆以六七日之间。其愈皆以十日以上者何也？ 不知其解。愿闻其故。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200844,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '1、黄帝问曰：今夫热病者。皆伤寒之类也。或愈或死。其死皆以六七日之间。其愈皆以十日以上者何也？ 不知其解。愿闻其故。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LtrwuxzdP0T', 4, '{"title":"第20200845条・热论篇第三十一","description":"<p>2、岐伯对曰：巨阳者。诸阳之属也。其脉连于风府。故为诸阳主气也。人之伤于寒也。则为病热。热虽甚不死。其两感于寒而病者。必不免于死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200845,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2、岐伯对曰：巨阳者。诸阳之属也。其脉连于风府。故为诸阳主气也。人之伤于寒也。则为病热。热虽甚不死。其两感于寒而病者。必不免于死。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z124G0haFPu', 4, '{"title":"第20200846条・热论篇第三十一","description":"<p>3、帝曰：愿闻其状。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200846,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '3、帝曰：愿闻其状。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1YjUpktCf5t', 4, '{"title":"第20200847条・热论篇第三十一","description":"<p>4、岐伯曰：伤寒一日。巨阳受之。故头项痛腰脊强。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200847,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '4、岐伯曰：伤寒一日。巨阳受之。故头项痛腰脊强。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('erIWWumQ3nA', 4, '{"title":"第20200848条・热论篇第三十一","description":"<p>5、二日阳明受之。阳明主肉。其脉挟鼻络于目。故身热目疼而鼻干。不得卧也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200848,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '5、二日阳明受之。阳明主肉。其脉挟鼻络于目。故身热目疼而鼻干。不得卧也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v1eTkLr23QR', 4, '{"title":"第20200849条・热论篇第三十一","description":"<p>6、三日少阳受之。少阳主胆。其脉循胁络于耳。故胸胁痛而耳聋。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200849,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '6、三日少阳受之。少阳主胆。其脉循胁络于耳。故胸胁痛而耳聋。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r9AFby4mGYp', 4, '{"title":"第20200850条・热论篇第三十一","description":"<p>7、三阳经络皆受其病。而未入于藏者。故可汗而已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200850,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '7、三阳经络皆受其病。而未入于藏者。故可汗而已。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R0iOi7CBFCj', 4, '{"title":"第20200851条・热论篇第三十一","description":"<p>8、四日太阴受之。太阴脉布胃中络于嗌。故腹满而嗌干。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200851,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '8、四日太阴受之。太阴脉布胃中络于嗌。故腹满而嗌干。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R8PuxLz1NUf', 4, '{"title":"第20200852条・热论篇第三十一","description":"<p>9、五日少阴受之。少阴脉贯肾络于肺。系舌本。故口燥舌干而渴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200852,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '9、五日少阴受之。少阴脉贯肾络于肺。系舌本。故口燥舌干而渴。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nJVpejgIzhf', 4, '{"title":"第20200853条・热论篇第三十一","description":"<p>10、六日厥阴受之。厥阴脉循阴器而络于肝。故烦满而囊缩。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200853,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '10、六日厥阴受之。厥阴脉循阴器而络于肝。故烦满而囊缩。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O91RjiLIxuf', 4, '{"title":"第20200854条・热论篇第三十一","description":"<p>11、三阴三阳。五脏六腑皆受病。荣卫不行。五脏不通。则死矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200854,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '11、三阴三阳。五脏六腑皆受病。荣卫不行。五脏不通。则死矣。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
