INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w0wB0xQHzJS', 4, '{"title":"第20200863条・热论篇第三十一","description":"<p>20、其未满三日者。可汗而已。其满三日者。可泄而已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200863,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '20、其未满三日者。可汗而已。其满三日者。可泄而已。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7USYXt3MlNn', 4, '{"title":"第20200864条・热论篇第三十一","description":"<p>21、帝曰：热病已愈。时有所遗者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200864,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '21、帝曰：热病已愈。时有所遗者何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ToDPhjN0eRt', 4, '{"title":"第20200865条・热论篇第三十一","description":"<p>22、岐伯曰：诸遗者。热甚而强食之。故有所遗也。若此者。皆病已衰而热有所藏。因其谷气相薄。两热相合。故有所遗也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200865,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '22、岐伯曰：诸遗者。热甚而强食之。故有所遗也。若此者。皆病已衰而热有所藏。因其谷气相薄。两热相合。故有所遗也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dE5nUqT6zy9', 4, '{"title":"第20200866条・热论篇第三十一","description":"<p>23、帝曰：善。治遗奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200866,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '23、帝曰：善。治遗奈何？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1OHGTj4E2tA', 4, '{"title":"第20200867条・热论篇第三十一","description":"<p>24、岐伯曰：视其虚实。调其逆从。可使必已矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200867,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '24、岐伯曰：视其虚实。调其逆从。可使必已矣。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2qHG303NRyj', 4, '{"title":"第20200868条・热论篇第三十一","description":"<p>25、帝曰：病热当何禁之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200868,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '25、帝曰：病热当何禁之？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pLw7Sn9eRJS', 4, '{"title":"第20200869条・热论篇第三十一","description":"<p>26、岐伯曰：病热少愈。食肉则复。多食则遗。此其禁也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200869,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '26、岐伯曰：病热少愈。食肉则复。多食则遗。此其禁也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p4XWcjXIBEk', 4, '{"title":"第20200870条・热论篇第三十一","description":"<p>27、帝曰：其病两感于寒者。其脉应与其病形何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200870,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '27、帝曰：其病两感于寒者。其脉应与其病形何如？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GLA2KcUtMNX', 4, '{"title":"第20200871条・热论篇第三十一","description":"<p>28、岐伯曰：两感于寒者。病一日则巨阳与少阴俱病。则头痛口干而烦满。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200871,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '28、岐伯曰：两感于寒者。病一日则巨阳与少阴俱病。则头痛口干而烦满。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Du0wFynPkWE', 4, '{"title":"第20200872条・热论篇第三十一","description":"<p>29、二日则阳明与太阴俱病。则腹满身热。不欲食谵言。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200872,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '29、二日则阳明与太阴俱病。则腹满身热。不欲食谵言。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('42AjKVMjWve', 4, '{"title":"第20200873条・热论篇第三十一","description":"<p>30、三日则少阳与厥阴俱病。则耳聋囊缩而厥。水浆不入。不知人者。六日死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200873,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '30、三日则少阳与厥阴俱病。则耳聋囊缩而厥。水浆不入。不知人者。六日死。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h4YFs8pTLtn', 4, '{"title":"第20200874条・热论篇第三十一","description":"<p>31、帝曰：五藏已伤。六腑不通。荣卫不行。如是之后。三日乃死何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200874,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '31、帝曰：五藏已伤。六腑不通。荣卫不行。如是之后。三日乃死何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7H8V6d6qmX2', 4, '{"title":"第20200875条・热论篇第三十一","description":"<p>32、岐伯曰：阳明者。十二经脉之长也。其血气盛。故不知人。三日其气乃尽。故死矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200875,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '32、岐伯曰：阳明者。十二经脉之长也。其血气盛。故不知人。三日其气乃尽。故死矣。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ok0TKSGzqfH', 4, '{"title":"第20200876条・热论篇第三十一","description":"<p>33、凡病伤寒而成温者。先夏至日者为病温。后夏至日者为病暑。暑当与汗皆出，勿止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200876,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '33、凡病伤寒而成温者。先夏至日者为病温。后夏至日者为病暑。暑当与汗皆出，勿止。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'bns9XytVw6v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tuupbeylukd', 4, '{"title":"第20200877条・刺热篇第三十二","description":"<p>1、肝热病者。小便先黄。腹痛多卧身热。热争则狂言及惊。胁满痛。手足躁。不得安卧。庚辛甚。甲乙大汗。气逆则庚辛死。刺足厥阴少阳。其逆则头痛员员。脉引冲头也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200877,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '1、肝热病者。小便先黄。腹痛多卧身热。热争则狂言及惊。胁满痛。手足躁。不得安卧。庚辛甚。甲乙大汗。气逆则庚辛死。刺足厥阴少阳。其逆则头痛员员。脉引冲头也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('79EBRBrXsy4', 4, '{"title":"第20200878条・刺热篇第三十二","description":"<p>2、心热病者。先不乐。数日乃热。热争则卒心痛。烦闷善呕。头痛面赤无汗。壬癸甚。丙丁大汗。气逆则壬癸死。刺手少阴太阳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200878,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2、心热病者。先不乐。数日乃热。热争则卒心痛。烦闷善呕。头痛面赤无汗。壬癸甚。丙丁大汗。气逆则壬癸死。刺手少阴太阳。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uqksONGLbaS', 4, '{"title":"第20200879条・刺热篇第三十二","description":"<p>3、脾热病者。先头重颊痛。烦心颜青。欲呕身热。热争则腰痛不可用俯仰。腹满泄。两颔痛。甲乙甚。戊己大汗。气逆则甲乙死。刺足太阴阳明。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200879,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '3、脾热病者。先头重颊痛。烦心颜青。欲呕身热。热争则腰痛不可用俯仰。腹满泄。两颔痛。甲乙甚。戊己大汗。气逆则甲乙死。刺足太阴阳明。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WRxgXiLUO6t', 4, '{"title":"第20200880条・刺热篇第三十二","description":"<p>4、肺热病者。先淅然厥。起毫毛。恶风寒。舌上黄身热。热争则喘咳。痛走胸膺背。不得大息。头痛不堪。汗出而寒。丙丁甚。庚辛大汗。气逆则丙丁死。刺手太阴阳明。出血如大豆。立已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200880,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '4、肺热病者。先淅然厥。起毫毛。恶风寒。舌上黄身热。热争则喘咳。痛走胸膺背。不得大息。头痛不堪。汗出而寒。丙丁甚。庚辛大汗。气逆则丙丁死。刺手太阴阳明。出血如大豆。立已。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u1YC3yg0zuP', 4, '{"title":"第20200881条・刺热篇第三十二","description":"<p>5、肾热病者。先腰痛酸。苦渴数饮身热。热争则项痛而强。䯒寒且酸。足下热。不欲言。其逆则项痛员员淡淡然。戊己甚。壬癸大汗。气逆则戊己死。刺足少阴太阳。诸汗者。至其所胜日汗出也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200881,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '5、肾热病者。先腰痛酸。苦渴数饮身热。热争则项痛而强。䯒寒且酸。足下热。不欲言。其逆则项痛员员淡淡然。戊己甚。壬癸大汗。气逆则戊己死。刺足少阴太阳。诸汗者。至其所胜日汗出也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6KJF80x6XEL', 4, '{"title":"第20200882条・刺热篇第三十二","description":"<p>6、肝热病者左颊先赤。心热病者颜先赤。脾热病者鼻先赤。肺热病者右颊先赤。肾热病者颐先赤。病虽未发。见赤色者刺之。名曰治未病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200882,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '6、肝热病者左颊先赤。心热病者颜先赤。脾热病者鼻先赤。肺热病者右颊先赤。肾热病者颐先赤。病虽未发。见赤色者刺之。名曰治未病。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3DO0jS2cdQQ', 4, '{"title":"第20200883条・刺热篇第三十二","description":"<p>7、热病从部所起者。至期而已。其刺之反者。三周而已。重逆则死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200883,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '7、热病从部所起者。至期而已。其刺之反者。三周而已。重逆则死。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('szwW7dq6VFU', 4, '{"title":"第20200884条・刺热篇第三十二","description":"<p>8、诸当汗者。至其所胜日。汗大出也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200884,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '8、诸当汗者。至其所胜日。汗大出也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2AuG16Z4Ryy', 4, '{"title":"第20200885条・刺热篇第三十二","description":"<p>9、诸治热病，以饮之寒水乃刺之。必寒衣之。居止寒处。身寒而止也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200885,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '9、诸治热病，以饮之寒水乃刺之。必寒衣之。居止寒处。身寒而止也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3JFEXdfbNb4', 4, '{"title":"第20200886条・刺热篇第三十二","description":"<p>10、热病先胸胁痛。手足躁。刺足少阳。补足太阴。病甚者为五十九刺。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200886,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '10、热病先胸胁痛。手足躁。刺足少阳。补足太阴。病甚者为五十九刺。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lplmi4tuFIa', 4, '{"title":"第20200887条・刺热篇第三十二","description":"<p>11、热病始手臂痛者。刺手阳明太阴而汗出止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200887,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '11、热病始手臂痛者。刺手阳明太阴而汗出止。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u0QiKgD6DD3', 4, '{"title":"第20200888条・刺热篇第三十二","description":"<p>12、热病始于头首者。刺项太阳而汗出止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200888,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '12、热病始于头首者。刺项太阳而汗出止。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gPCfHvMspvb', 4, '{"title":"第20200889条・刺热篇第三十二","description":"<p>13、热病始于足胫者。刺足阳明而汗出止。 热</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200889,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '13、热病始于足胫者。刺足阳明而汗出止。 热', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VrN2MZarHvq', 4, '{"title":"第20200890条・刺热篇第三十二","description":"<p>14、病先身重骨痛。耳聋好瞑。刺足少阴。病甚为五十九刺。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200890,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '14、病先身重骨痛。耳聋好瞑。刺足少阴。病甚为五十九刺。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aIAuN7XSyuE', 4, '{"title":"第20200891条・刺热篇第三十二","description":"<p>15、热病先眩冒而热。胸胁满。刺足少阴少阳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200891,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '15、热病先眩冒而热。胸胁满。刺足少阴少阳。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CXJIyEYB30O', 4, '{"title":"第20200892条・刺热篇第三十二","description":"<p>16、太阳之脉。色荣颧骨。热病也。荣未交。曰今且得汗。待时而已。与厥阴脉争见者。死期不过三日。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200892,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '16、太阳之脉。色荣颧骨。热病也。荣未交。曰今且得汗。待时而已。与厥阴脉争见者。死期不过三日。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9j43TMabNwu', 4, '{"title":"第20200893条・刺热篇第三十二","description":"<p>17、其热病内连肾。少阳之脉色也。少阳之脉。色荣颊前。热病也。荣未交。曰今且得汗。待时而已。与少阴脉争见者。死期不过三日。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200893,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '17、其热病内连肾。少阳之脉色也。少阳之脉。色荣颊前。热病也。荣未交。曰今且得汗。待时而已。与少阴脉争见者。死期不过三日。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a7BA1G5ZOlj', 4, '{"title":"第20200894条・刺热篇第三十二","description":"<p>18、热病气穴：三椎下间主胸中热。四椎下间主膈中热。五椎下间主肝热。六椎下间主脾热。七椎下间主肾热。荣在骶也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200894,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '18、热病气穴：三椎下间主胸中热。四椎下间主膈中热。五椎下间主肝热。六椎下间主脾热。七椎下间主肾热。荣在骶也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('06GVQJuX9Tg', 4, '{"title":"第20200895条・刺热篇第三十二","description":"<p>19、项上三椎陷者中也。颊下逆颧为大瘕。下牙车为腹满。颧后为胁痛。颊上者膈上也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200895,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '19、项上三椎陷者中也。颊下逆颧为大瘕。下牙车为腹满。颧后为胁痛。颊上者膈上也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vlhYKx3gkfu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sEOkUp4alSa', 4, '{"title":"第20200896条・评热病论篇第三十三","description":"<p>1、黄帝问曰：有病温者。汗出辄复热。而脉躁疾不为汗衰。狂言不能食。病名为何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200896,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '1、黄帝问曰：有病温者。汗出辄复热。而脉躁疾不为汗衰。狂言不能食。病名为何？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZPE6XonXvwT', 4, '{"title":"第20200897条・评热病论篇第三十三","description":"<p>2、岐伯对曰：病名阴阳交。交者死也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200897,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2、岐伯对曰：病名阴阳交。交者死也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BwrpppGY8EN', 4, '{"title":"第20200898条・评热病论篇第三十三","description":"<p>3、帝曰：愿闻其说。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200898,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '3、帝曰：愿闻其说。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4tPdfr0Khr7', 4, '{"title":"第20200899条・评热病论篇第三十三","description":"<p>4、岐伯曰：人所以汗出者。皆生于谷。谷生于精。今邪气交争于骨肉而得汗者。是邪却而精胜也。精胜则当能食而不复热。复热者邪气也。汗者精气也。今汗出而辄复热者。是邪胜也。不能食者。精无俾也。病而留者。其寿可立而倾也。且夫《热论》曰：汗出而脉尚躁盛者死。今脉不与汗相应。此不胜其病也。其死明矣。狂言者是失志。失志者死。今见三死。不见一生。虽愈必死也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200899,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '4、岐伯曰：人所以汗出者。皆生于谷。谷生于精。今邪气交争于骨肉而得汗者。是邪却而精胜也。精胜则当能食而不复热。复热者邪气也。汗者精气也。今汗出而辄复热者。是邪胜也。不能食者。精无俾也。病而留者。其寿可立而倾也。且夫《热论》曰：汗出而脉尚躁盛者死。今脉不与汗相应。此不胜其病也。其死明矣。狂言者是失志。失志者死。今见三死。不见一生。虽愈必死也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nXE9It8koyV', 4, '{"title":"第20200900条・评热病论篇第三十三","description":"<p>5、帝曰：有病身热汗出烦满。烦满不为汗解。此为何病？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200900,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '5、帝曰：有病身热汗出烦满。烦满不为汗解。此为何病？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NrcdDvMtmgr', 4, '{"title":"第20200901条・评热病论篇第三十三","description":"<p>6、岐伯曰：汗出而身热者风也。汗出而烦满不解者厥也。病名曰风厥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200901,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '6、岐伯曰：汗出而身热者风也。汗出而烦满不解者厥也。病名曰风厥。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nHKgsslDarF', 4, '{"title":"第20200902条・评热病论篇第三十三","description":"<p>7、帝曰：愿卒闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200902,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '7、帝曰：愿卒闻之。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
