INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dBy67beGa9n', 4, '{"title":"第20200906条・评热病论篇第三十三","description":"<p>11、帝曰：劳风为病何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200906,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '11、帝曰：劳风为病何如？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N3gtQC0SmYo', 4, '{"title":"第20200907条・评热病论篇第三十三","description":"<p>12、岐伯曰：劳风法在肺下。其为病也。使人强上冥视。唾出若涕。恶风而振寒。此为劳风之病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200907,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '12、岐伯曰：劳风法在肺下。其为病也。使人强上冥视。唾出若涕。恶风而振寒。此为劳风之病。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3vH3H6QOGPA', 4, '{"title":"第20200908条・评热病论篇第三十三","description":"<p>13、帝曰： 治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200908,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '13、帝曰： 治之奈何？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ws24Io6T8AC', 4, '{"title":"第20200909条・评热病论篇第三十三","description":"<p>14、岐伯曰：以救俯仰。巨阳引精者三日。中年者五日。不精者七日。咳出青黄涕。其状如脓。大如弹丸。从口中若鼻中出。不出则伤肺。伤肺则死也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200909,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '14、岐伯曰：以救俯仰。巨阳引精者三日。中年者五日。不精者七日。咳出青黄涕。其状如脓。大如弹丸。从口中若鼻中出。不出则伤肺。伤肺则死也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mzOP8mU6xz5', 4, '{"title":"第20200910条・评热病论篇第三十三","description":"<p>15、帝曰：有病肾风者。面庬然壅。害于言。可刺不？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200910,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '15、帝曰：有病肾风者。面庬然壅。害于言。可刺不？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nAiOQSsR54X', 4, '{"title":"第20200911条・评热病论篇第三十三","description":"<p>16、岐伯曰：虚不当刺。不当刺而刺。后五日其气必至。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200911,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '16、岐伯曰：虚不当刺。不当刺而刺。后五日其气必至。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JrPIfGEnIX7', 4, '{"title":"第20200912条・评热病论篇第三十三","description":"<p>17、帝曰：其至何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200912,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '17、帝曰：其至何如？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F0sQ2puyFSX', 4, '{"title":"第20200913条・评热病论篇第三十三","description":"<p>18、岐伯曰：至必少气时热。时热从胸背上至头。汗出手热。口干苦渴。小便黄。目下肿。腹中鸣。身重难以行。月事不来。烦而不能食。不能正偃。正偃则咳甚。病名曰风水。论在《刺法》中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200913,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '18、岐伯曰：至必少气时热。时热从胸背上至头。汗出手热。口干苦渴。小便黄。目下肿。腹中鸣。身重难以行。月事不来。烦而不能食。不能正偃。正偃则咳甚。病名曰风水。论在《刺法》中。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lhNzqmNuqh2', 4, '{"title":"第20200914条・评热病论篇第三十三","description":"<p>19、帝曰：愿闻 其说。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200914,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '19、帝曰：愿闻 其说。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hQiUyE0oRy6', 4, '{"title":"第20200915条・评热病论篇第三十三","description":"<p>20、岐伯曰：邪之所凑。其气必虚。阴虚者阳必凑之。故少气时热而汗出也。小便黄者。少腹中有热也。不能正偃者。胃中不和也。正偃则咳甚。上迫肺也。诸有水气者。微肿先见于目下也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200915,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '20、岐伯曰：邪之所凑。其气必虚。阴虚者阳必凑之。故少气时热而汗出也。小便黄者。少腹中有热也。不能正偃者。胃中不和也。正偃则咳甚。上迫肺也。诸有水气者。微肿先见于目下也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('StlqOmysqD7', 4, '{"title":"第20200916条・评热病论篇第三十三","description":"<p>21、帝曰：何以言？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200916,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '21、帝曰：何以言？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p8IKfaQU0Y1', 4, '{"title":"第20200917条・评热病论篇第三十三","description":"<p>22、岐伯曰： 水者阴也。目下亦阴也。腹者至阴之所居。故水在腹者。必使目下肿也。真气上逆。故口苦舌干。卧不得正偃。正偃则咳出清水也。诸水病者。故不得卧。卧则惊。惊则咳甚也。腹中鸣者，病本于胃也。薄脾则烦不能食。食不下者。胃脘隔也。身重难以行者。胃脉在足也。月事不来者。胞脉闭也。胞脉者属心而络于胞中。今气上迫肺。心气不得下通。故月事不来也。帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200917,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '22、岐伯曰： 水者阴也。目下亦阴也。腹者至阴之所居。故水在腹者。必使目下肿也。真气上逆。故口苦舌干。卧不得正偃。正偃则咳出清水也。诸水病者。故不得卧。卧则惊。惊则咳甚也。腹中鸣者，病本于胃也。薄脾则烦不能食。食不下者。胃脘隔也。身重难以行者。胃脉在足也。月事不来者。胞脉闭也。胞脉者属心而络于胞中。今气上迫肺。心气不得下通。故月事不来也。帝曰：善。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'gf3RS1l0cEz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XdgsJTMtbm8', 4, '{"title":"第20200918条・逆调论篇第三十四","description":"<p>1、黄帝问曰：人身非常温也。非常热也。为之热而烦满者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200918,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '1、黄帝问曰：人身非常温也。非常热也。为之热而烦满者何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('462ntA5tXee', 4, '{"title":"第20200919条・逆调论篇第三十四","description":"<p>2、岐伯对曰：阴气少而阳气胜。故热而烦满也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200919,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2、岐伯对曰：阴气少而阳气胜。故热而烦满也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VA1EPZ1U2dB', 4, '{"title":"第20200920条・逆调论篇第三十四","description":"<p>3、帝曰：人身非衣寒也。中非有寒气也。寒从中生者何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200920,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '3、帝曰：人身非衣寒也。中非有寒气也。寒从中生者何？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bVK1ws8wvdF', 4, '{"title":"第20200921条・逆调论篇第三十四","description":"<p>4、岐伯曰：是人多痹气也。阳气少。阴气多。故身寒如从水中出。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200921,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '4、岐伯曰：是人多痹气也。阳气少。阴气多。故身寒如从水中出。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xy3AqHS3TCc', 4, '{"title":"第20200922条・逆调论篇第三十四","description":"<p>5、帝曰：人有四肢热。逢风寒如炙如火者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200922,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '5、帝曰：人有四肢热。逢风寒如炙如火者何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('95BK6n2phix', 4, '{"title":"第20200923条・逆调论篇第三十四","description":"<p>6、岐伯曰：是人者阴气虚。阳气盛。四肢者阳也。两阳相得而阴气虚少。少水不能灭盛火。而阳独治。独治者不能生长也。独胜而止耳。逢风而如炙如火者。是人当肉烁也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200923,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '6、岐伯曰：是人者阴气虚。阳气盛。四肢者阳也。两阳相得而阴气虚少。少水不能灭盛火。而阳独治。独治者不能生长也。独胜而止耳。逢风而如炙如火者。是人当肉烁也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9NyNn0Lx2gd', 4, '{"title":"第20200924条・逆调论篇第三十四","description":"<p>7、帝曰：人有身寒。汤火不能热。浓衣不能温。然不冻栗。是为何病？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200924,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '7、帝曰：人有身寒。汤火不能热。浓衣不能温。然不冻栗。是为何病？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XiJ1uGUQr5l', 4, '{"title":"第20200925条・逆调论篇第三十四","description":"<p>8、岐伯曰：是人者。素肾气胜。以水为事。太阳气衰。肾脂枯不长。一水不能胜两火。肾者水也。而生于骨。肾不生则髓不能满。故寒甚至骨也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200925,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '8、岐伯曰：是人者。素肾气胜。以水为事。太阳气衰。肾脂枯不长。一水不能胜两火。肾者水也。而生于骨。肾不生则髓不能满。故寒甚至骨也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gqFlgYlb6c5', 4, '{"title":"第20200926条・逆调论篇第三十四","description":"<p>9、所以不能冻栗者。肝一阳也。心二阳也。肾孤脏也。一水不能胜二火。故不能冻栗。病名曰骨痹。是人当挛节也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200926,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '9、所以不能冻栗者。肝一阳也。心二阳也。肾孤脏也。一水不能胜二火。故不能冻栗。病名曰骨痹。是人当挛节也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a9OxXI3OzcW', 4, '{"title":"第20200927条・逆调论篇第三十四","description":"<p>10、帝曰：人之肉苛者。虽近衣絮。犹尚苛也。是谓何疾？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200927,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '10、帝曰：人之肉苛者。虽近衣絮。犹尚苛也。是谓何疾？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RzTkfwDtxyw', 4, '{"title":"第20200928条・逆调论篇第三十四","description":"<p>11、岐伯曰：荣气虚。卫气实也。荣气虚则不仁。卫气虚则不用。荣卫俱虚。则不仁且不用。肉如故也。人身与志不相有。曰死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200928,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '11、岐伯曰：荣气虚。卫气实也。荣气虚则不仁。卫气虚则不用。荣卫俱虚。则不仁且不用。肉如故也。人身与志不相有。曰死。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jk2EmXyp7St', 4, '{"title":"第20200929条・逆调论篇第三十四","description":"<p>12、帝曰：人有逆气不得卧而息有音者。有不得 。卧而息无音者。有起居如故而息有音者。有得卧行而喘者。有不得卧不能行而喘者。有不得卧卧而喘者。皆何脏使然？愿闻其故。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200929,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '12、帝曰：人有逆气不得卧而息有音者。有不得 。卧而息无音者。有起居如故而息有音者。有得卧行而喘者。有不得卧不能行而喘者。有不得卧卧而喘者。皆何脏使然？愿闻其故。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jebMr0PfUIs', 4, '{"title":"第20200930条・逆调论篇第三十四","description":"<p>13、岐伯曰：不得卧而息有音者。是阳明之逆也。足三阳者下行。今逆而上行。故息有音也。阳明者胃脉也。胃者六腑之海。其气亦下行。阳明逆不得从其道。故不得卧也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200930,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '13、岐伯曰：不得卧而息有音者。是阳明之逆也。足三阳者下行。今逆而上行。故息有音也。阳明者胃脉也。胃者六腑之海。其气亦下行。阳明逆不得从其道。故不得卧也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('43vVhIjjgin', 4, '{"title":"第20200931条・逆调论篇第三十四","description":"<p>14、《下经》曰：胃不和则卧不安。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200931,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '14、《下经》曰：胃不和则卧不安。此之谓也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mRzpwYSdxKr', 4, '{"title":"第20200932条・逆调论篇第三十四","description":"<p>15、夫起居如故而息有音者。此肺之络脉逆也。络脉不得随经上下。故留经而不行。络脉之病患也微。故起居如故而息有音也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200932,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '15、夫起居如故而息有音者。此肺之络脉逆也。络脉不得随经上下。故留经而不行。络脉之病患也微。故起居如故而息有音也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TLSGgwi9CZq', 4, '{"title":"第20200933条・逆调论篇第三十四","description":"<p>16、夫不得卧卧则喘者。是水气之客也。夫水者循津液而流也。肾者水藏。主津液。主卧与喘也。帝曰：</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200933,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '16、夫不得卧卧则喘者。是水气之客也。夫水者循津液而流也。肾者水藏。主津液。主卧与喘也。帝曰：', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'n3lcXl04HIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VfuWRAi3mAF', 4, '{"title":"第20200934条・疟论篇第三十五","description":"<p>1、黄帝问曰：夫疟皆生于风。其蓄作有时者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200934,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '1、黄帝问曰：夫疟皆生于风。其蓄作有时者何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OA3Pl3Ecx9E', 4, '{"title":"第20200935条・疟论篇第三十五","description":"<p>2、岐伯对曰：疟之始发也。先起于毫毛。伸欠乃作。寒栗鼓颔。腰脊俱痛。寒去则内外皆热。头痛如破。渴欲冷冻饮料。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200935,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2、岐伯对曰：疟之始发也。先起于毫毛。伸欠乃作。寒栗鼓颔。腰脊俱痛。寒去则内外皆热。头痛如破。渴欲冷冻饮料。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8ofwcW6dV1c', 4, '{"title":"第20200936条・疟论篇第三十五","description":"<p>3、帝曰：何气使然？愿闻其道。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200936,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '3、帝曰：何气使然？愿闻其道。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T6LlMAcJCkh', 4, '{"title":"第20200937条・疟论篇第三十五","description":"<p>4、岐伯曰：阴阳上下交争。虚实更作。阴阳相移也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200937,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '4、岐伯曰：阴阳上下交争。虚实更作。阴阳相移也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uT42Z7HVGnU', 4, '{"title":"第20200938条・疟论篇第三十五","description":"<p>5、阳并于阴。则阴实而阳虚。阳明虚则寒栗鼓颔也。巨阳虚则腰背头项痛。三阳俱虚则阴气胜。阴气胜则骨寒而痛。寒生于内。故中外皆寒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200938,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '5、阳并于阴。则阴实而阳虚。阳明虚则寒栗鼓颔也。巨阳虚则腰背头项痛。三阳俱虚则阴气胜。阴气胜则骨寒而痛。寒生于内。故中外皆寒。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RuXxPOt1iNR', 4, '{"title":"第20200939条・疟论篇第三十五","description":"<p>6、阳盛则外热。阴虚则内热。外内皆热则喘而渴。故欲冷饮也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200939,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '6、阳盛则外热。阴虚则内热。外内皆热则喘而渴。故欲冷饮也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aGGPZLvGHdx', 4, '{"title":"第20200940条・疟论篇第三十五","description":"<p>7、此皆得之夏伤于暑。热气盛。藏于皮肤之内。肠胃之外。此荣气之所舍也。此令人汗空疏。腠理开。因得秋气。汗出遇风。及得之以浴。水气舍于皮肤之内。与卫气并居。卫气者。昼日行于阳。夜行于阴。此气得阳而外出。得阴而内薄。内外相薄。是以日作。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200940,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '7、此皆得之夏伤于暑。热气盛。藏于皮肤之内。肠胃之外。此荣气之所舍也。此令人汗空疏。腠理开。因得秋气。汗出遇风。及得之以浴。水气舍于皮肤之内。与卫气并居。卫气者。昼日行于阳。夜行于阴。此气得阳而外出。得阴而内薄。内外相薄。是以日作。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZntYI2zxHqM', 4, '{"title":"第20200941条・疟论篇第三十五","description":"<p>8、帝曰：其间日而作者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200941,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '8、帝曰：其间日而作者何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SLdualMojM0', 4, '{"title":"第20200942条・疟论篇第三十五","description":"<p>9、岐伯曰：其气之舍深。内薄于阴。阳气独发。阴邪内着。阴与阳争不得出。是以间日而作也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200942,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '9、岐伯曰：其气之舍深。内薄于阴。阳气独发。阴邪内着。阴与阳争不得出。是以间日而作也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zbJ7lrARK7L', 4, '{"title":"第20200943条・疟论篇第三十五","description":"<p>10、帝曰：善。其作日晏与其日早者。何气使然？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200943,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '10、帝曰：善。其作日晏与其日早者。何气使然？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HtU1Ng4w1ka', 4, '{"title":"第20200944条・疟论篇第三十五","description":"<p>11、岐伯曰：邪气客于风府。循膂而下。卫气一日一夜大会于风府。其明日日下一节。故其作也晏。此先客于脊背也。每至于风府则腠理开。腠理开则邪气入。邪气入则病作。以此日作稍益晏也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200944,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '11、岐伯曰：邪气客于风府。循膂而下。卫气一日一夜大会于风府。其明日日下一节。故其作也晏。此先客于脊背也。每至于风府则腠理开。腠理开则邪气入。邪气入则病作。以此日作稍益晏也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yIrKX3WKYpg', 4, '{"title":"第20200945条・疟论篇第三十五","description":"<p>12、其出于风府。日下一节。二十五日下至骶骨。二十六日入于脊内。注于伏膂之脉。其气上行。九日出于缺盆之中。其气日高。故作日益早也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200945,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '12、其出于风府。日下一节。二十五日下至骶骨。二十六日入于脊内。注于伏膂之脉。其气上行。九日出于缺盆之中。其气日高。故作日益早也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kbYXqR3hHPk', 4, '{"title":"第20200946条・疟论篇第三十五","description":"<p>13、其间日发者。由邪气内薄于五脏。横连募原也。其道远。其气深。其行迟。不能与卫气俱行。不得皆出。故间日乃作也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200946,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '13、其间日发者。由邪气内薄于五脏。横连募原也。其道远。其气深。其行迟。不能与卫气俱行。不得皆出。故间日乃作也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4X09ttboMO6', 4, '{"title":"第20200947条・疟论篇第三十五","description":"<p>14、帝曰：夫子言卫气每至于风府。腠理乃发。发则邪气入。入则病作。今卫气日下一节。其气之发也不当风府。其日作者奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200947,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '14、帝曰：夫子言卫气每至于风府。腠理乃发。发则邪气入。入则病作。今卫气日下一节。其气之发也不当风府。其日作者奈何？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y5K54qvvkAZ', 4, '{"title":"第20200948条・疟论篇第三十五","description":"<p>15、岐伯曰：此邪气客于头项循膂而下者也。故虚实不同。邪中异所。则不得当其风府也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200948,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '15、岐伯曰：此邪气客于头项循膂而下者也。故虚实不同。邪中异所。则不得当其风府也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pqfOnW6O2dn', 4, '{"title":"第20200949条・疟论篇第三十五","description":"<p>16、故邪中于头项者。气至头项而病。中于背者。气至背而病。中于腰脊者。气至腰脊而病。中于手足者。气至手足而病。卫气之所在。与邪气相合。则病作。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200949,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '16、故邪中于头项者。气至头项而病。中于背者。气至背而病。中于腰脊者。气至腰脊而病。中于手足者。气至手足而病。卫气之所在。与邪气相合。则病作。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GR6ywzc1n0B', 4, '{"title":"第20200950条・疟论篇第三十五","description":"<p>17、故风无常府。卫气之所发。必开其腠理。邪气之所合。则其府也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200950,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '17、故风无常府。卫气之所发。必开其腠理。邪气之所合。则其府也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nv1LxmCgQKv', 4, '{"title":"第20200951条・疟论篇第三十五","description":"<p>18、帝曰：善。夫风之与疟也。相似同类。而风独常在。疟得有时而休者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200951,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '18、帝曰：善。夫风之与疟也。相似同类。而风独常在。疟得有时而休者何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KuBt0n1QFPZ', 4, '{"title":"第20200952条・疟论篇第三十五","description":"<p>19、岐伯曰：风气留其处。故常在。疟气随经络沉以内薄。故卫气应乃作。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200952,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '19、岐伯曰：风气留其处。故常在。疟气随经络沉以内薄。故卫气应乃作。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dUj80UCYYTF', 4, '{"title":"第20200953条・疟论篇第三十五","description":"<p>20、帝曰：疟先寒而后热者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200953,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '20、帝曰：疟先寒而后热者何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DLG1Apjg0vD', 4, '{"title":"第20200954条・疟论篇第三十五","description":"<p>21、岐伯曰：夏伤于大暑。其汗大出。腠理开发。因遇夏气凄沧之水寒。藏于腠理皮肤之中。秋伤于风。则病成矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200954,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '21、岐伯曰：夏伤于大暑。其汗大出。腠理开发。因遇夏气凄沧之水寒。藏于腠理皮肤之中。秋伤于风。则病成矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K71e873ivYc', 4, '{"title":"第20200955条・疟论篇第三十五","description":"<p>22、夫寒者阴气也。风者阳气也。先伤于寒而后伤于风。故先寒而后热也。病以时作。名曰寒疟。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200955,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '22、夫寒者阴气也。风者阳气也。先伤于寒而后伤于风。故先寒而后热也。病以时作。名曰寒疟。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qcUsnXNohYQ', 4, '{"title":"第20200956条・疟论篇第三十五","description":"<p>23、帝曰：先热而后寒者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200956,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '23、帝曰：先热而后寒者何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Bh2uixmRfPx', 4, '{"title":"第20200957条・疟论篇第三十五","description":"<p>24、岐伯曰：此先伤于风而后伤于寒。故先热而后寒也。亦以时作。名曰温疟。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200957,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '24、岐伯曰：此先伤于风而后伤于寒。故先热而后寒也。亦以时作。名曰温疟。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7CWCKvg3HYl', 4, '{"title":"第20200958条・疟论篇第三十五","description":"<p>25、其但热而不寒者。阴气先绝。阳气独发。则少气烦冤。手足热而欲呕。名曰瘅疟。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200958,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '25、其但热而不寒者。阴气先绝。阳气独发。则少气烦冤。手足热而欲呕。名曰瘅疟。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6eGCfdjwg3x', 4, '{"title":"第20200959条・疟论篇第三十五","description":"<p>26、帝曰：夫经言有余者泻之。不足者补之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200959,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '26、帝曰：夫经言有余者泻之。不足者补之。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5yEtsAKPL6A', 4, '{"title":"第20200960条・疟论篇第三十五","description":"<p>27、今热为有余。寒为不足。夫疟者之寒。汤火不能温也。及其热。冰水不能寒也。此皆有余不足之类。当此之时。良工不能止。必须其自衰乃刺之。其故何也？愿闻其说。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200960,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '27、今热为有余。寒为不足。夫疟者之寒。汤火不能温也。及其热。冰水不能寒也。此皆有余不足之类。当此之时。良工不能止。必须其自衰乃刺之。其故何也？愿闻其说。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2Xs8EnXyqeI', 4, '{"title":"第20200961条・疟论篇第三十五","description":"<p>28、岐伯曰：经言无刺熇熇之热。无刺浑浑之脉。无刺漉漉之汗。故为其病逆未可治也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200961,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '28、岐伯曰：经言无刺熇熇之热。无刺浑浑之脉。无刺漉漉之汗。故为其病逆未可治也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FCfYv5t27iF', 4, '{"title":"第20200962条・疟论篇第三十五","description":"<p>29、夫疟之始发也。阳气并于阴。当是之时。阳虚而阴盛。外无气。故先寒栗也。阴气逆极。则复出之阳。阳与阴复并于外。则阴虚而阳实。故先热而渴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200962,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '29、夫疟之始发也。阳气并于阴。当是之时。阳虚而阴盛。外无气。故先寒栗也。阴气逆极。则复出之阳。阳与阴复并于外。则阴虚而阳实。故先热而渴。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nUTWJwC92T2', 4, '{"title":"第20200963条・疟论篇第三十五","description":"<p>30、夫疟气者。并于阳则阳胜。并于阴则阴胜。阴胜则寒。阳胜则热。疟者。风寒之气不常也。病极则复。至病之发也。如火之热。如风雨不可当也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200963,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '30、夫疟气者。并于阳则阳胜。并于阴则阴胜。阴胜则寒。阳胜则热。疟者。风寒之气不常也。病极则复。至病之发也。如火之热。如风雨不可当也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9MDOcAH4zxB', 4, '{"title":"第20200964条・疟论篇第三十五","description":"<p>31、故经言曰：方其盛时必毁。因其衰也。事必大昌。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200964,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '31、故经言曰：方其盛时必毁。因其衰也。事必大昌。此之谓也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b6azLslJY8q', 4, '{"title":"第20200965条・疟论篇第三十五","description":"<p>32、夫疟之未发也。阴未并阳。阳未并阴。因而调之。真气得安。邪气乃亡。故工不能治其已发。为其气逆也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200965,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '32、夫疟之未发也。阴未并阳。阳未并阴。因而调之。真气得安。邪气乃亡。故工不能治其已发。为其气逆也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DR310JOSUJF', 4, '{"title":"第20200966条・疟论篇第三十五","description":"<p>33、帝曰：善。攻之奈何？早晏何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200966,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '33、帝曰：善。攻之奈何？早晏何如？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LndEtXWFsmP', 4, '{"title":"第20200967条・疟论篇第三十五","description":"<p>34、岐伯曰：疟之且发也。阴阳之且移也。必从四末始也。阳已伤。阴从之。故先其时坚束其处。令邪气不得入。阴气不得出。审候见之。在孙络盛坚而血者皆取之。此真往而未得并者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200967,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '34、岐伯曰：疟之且发也。阴阳之且移也。必从四末始也。阳已伤。阴从之。故先其时坚束其处。令邪气不得入。阴气不得出。审候见之。在孙络盛坚而血者皆取之。此真往而未得并者也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n6XCtRkMeVS', 4, '{"title":"第20200968条・疟论篇第三十五","description":"<p>35、帝曰：疟不发。其应何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200968,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '35、帝曰：疟不发。其应何如？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Vu6jSZXLH4Z', 4, '{"title":"第20200969条・疟论篇第三十五","description":"<p>36、岐伯曰：疟气者。必更盛更虚。当气之所在也。病在阳。则热而脉躁。在阴。则寒而脉静。极则阴阳俱衰。卫气相离。故病得休。卫气集。则复病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200969,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '36、岐伯曰：疟气者。必更盛更虚。当气之所在也。病在阳。则热而脉躁。在阴。则寒而脉静。极则阴阳俱衰。卫气相离。故病得休。卫气集。则复病也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rdnhq73Gja7', 4, '{"title":"第20200970条・疟论篇第三十五","description":"<p>37、帝曰：时有间二日或至数日发。或渴或不渴。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200970,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '37、帝曰：时有间二日或至数日发。或渴或不渴。其故何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lTyIiCGWwhA', 4, '{"title":"第20200971条・疟论篇第三十五","description":"<p>38、岐伯曰：其间日者。邪气与卫气客于六腑。而有时相失。不能相得。故休数日乃作也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200971,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '38、岐伯曰：其间日者。邪气与卫气客于六腑。而有时相失。不能相得。故休数日乃作也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c4X6QvU1FYF', 4, '{"title":"第20200972条・疟论篇第三十五","description":"<p>39、疟者。阴阳更胜也。或甚或不甚。故或渴或不渴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200972,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '39、疟者。阴阳更胜也。或甚或不甚。故或渴或不渴。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ymx2bTV8BMp', 4, '{"title":"第20200973条・疟论篇第三十五","description":"<p>40、帝曰：论言夏伤于暑。秋必病疟。今疟不必应者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200973,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '40、帝曰：论言夏伤于暑。秋必病疟。今疟不必应者何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zdUHNI11vXQ', 4, '{"title":"第20200974条・疟论篇第三十五","description":"<p>41、岐伯曰：此应四时者也。其病异形者。反四时也。其以秋病者寒甚。以冬病者寒不甚。以春病者恶风。以夏病者多汗。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200974,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '41、岐伯曰：此应四时者也。其病异形者。反四时也。其以秋病者寒甚。以冬病者寒不甚。以春病者恶风。以夏病者多汗。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8tpY9I296O2', 4, '{"title":"第20200975条・疟论篇第三十五","description":"<p>42、帝曰：夫病温疟与寒疟而皆安舍？舍于何脏？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200975,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '42、帝曰：夫病温疟与寒疟而皆安舍？舍于何脏？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OSDIWFsfbZ4', 4, '{"title":"第20200976条・疟论篇第三十五","description":"<p>43、岐伯曰：温疟者。得之冬中于风。寒气藏于骨髓之中。至春则阳气大发。邪气不能自出。因遇大暑。脑髓烁。肌肉消。腠理发泄。或有所用力。邪气与汗皆出。此病藏于肾。其气先从内出之于外也。如是者。阴虚而阳盛。阳盛则热矣。衰则气复反入。入则阳虚。阳虚则寒矣。故先热而后寒。名曰温疟。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200976,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '43、岐伯曰：温疟者。得之冬中于风。寒气藏于骨髓之中。至春则阳气大发。邪气不能自出。因遇大暑。脑髓烁。肌肉消。腠理发泄。或有所用力。邪气与汗皆出。此病藏于肾。其气先从内出之于外也。如是者。阴虚而阳盛。阳盛则热矣。衰则气复反入。入则阳虚。阳虚则寒矣。故先热而后寒。名曰温疟。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dgMCaTETWql', 4, '{"title":"第20200977条・疟论篇第三十五","description":"<p>44、帝曰：瘅疟何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200977,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '44、帝曰：瘅疟何如？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vhtx4SnIhDJ', 4, '{"title":"第20200978条・疟论篇第三十五","description":"<p>45、岐伯曰：瘅疟者。肺素有热气盛于身。厥逆上冲。中气实而不外泄。因有所用力。腠理开。风寒舍于皮肤之内。分肉之间而发。发则阳气盛。阳气盛而不衰则病矣。其气不及于阴。故但热而不寒。气内藏于心。而外舍于分肉之间。令人消烁脱肉，故命曰瘅疟。帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200978,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '45、岐伯曰：瘅疟者。肺素有热气盛于身。厥逆上冲。中气实而不外泄。因有所用力。腠理开。风寒舍于皮肤之内。分肉之间而发。发则阳气盛。阳气盛而不衰则病矣。其气不及于阴。故但热而不寒。气内藏于心。而外舍于分肉之间。令人消烁脱肉，故命曰瘅疟。帝曰：善。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'iCKrYKmrv1l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hZdn0sj9XlK', 4, '{"title":"第20200979条・刺疟篇第三十六","description":"<p>1、足太阳之疟。令人腰痛头重。寒从背起。先寒后热。熇熇暍暍然。热止汗出。难已。刺郄中出血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200979,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '1、足太阳之疟。令人腰痛头重。寒从背起。先寒后热。熇熇暍暍然。热止汗出。难已。刺郄中出血。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h5rzp0i4QFd', 4, '{"title":"第20200980条・刺疟篇第三十六","description":"<p>2、足少阳之疟。令人身体解?。寒不甚。热不甚。恶见人。见人心惕惕然。热多汗出甚。刺足少阳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200980,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2、足少阳之疟。令人身体解?。寒不甚。热不甚。恶见人。见人心惕惕然。热多汗出甚。刺足少阳。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UdE0j7jH9sJ', 4, '{"title":"第20200981条・刺疟篇第三十六","description":"<p>3、足阳明之疟。令人先寒。洒淅洒淅。寒甚久乃热。热去 出。喜见日月光火气乃快然。刺足阳明跗上。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200981,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '3、足阳明之疟。令人先寒。洒淅洒淅。寒甚久乃热。热去 出。喜见日月光火气乃快然。刺足阳明跗上。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oIH2xa2Y6RK', 4, '{"title":"第20200982条・刺疟篇第三十六","description":"<p>4、足太阴之疟。令人不乐。好大息。不嗜食。多寒热汗出。病至则善呕。呕已乃衰。即取之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200982,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '4、足太阴之疟。令人不乐。好大息。不嗜食。多寒热汗出。病至则善呕。呕已乃衰。即取之。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0u3k7eNkLwg', 4, '{"title":"第20200983条・刺疟篇第三十六","description":"<p>5、足少阴之疟。令人呕吐甚。多寒热。热多寒少。欲闭户牖而处。其病难已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200983,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '5、足少阴之疟。令人呕吐甚。多寒热。热多寒少。欲闭户牖而处。其病难已。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SQm1NK7NI1S', 4, '{"title":"第20200984条・刺疟篇第三十六","description":"<p>6、足厥阴之疟。令人腰痛少腹满。小便不利如癃状。非癃也。数便。意恐惧气不足。腹中悒悒。刺足厥阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200984,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '6、足厥阴之疟。令人腰痛少腹满。小便不利如癃状。非癃也。数便。意恐惧气不足。腹中悒悒。刺足厥阴。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AijFcnhu2LF', 4, '{"title":"第20200985条・刺疟篇第三十六","description":"<p>7、肺疟者。令人心寒。寒甚热。热间善惊。如有所见者。刺手太阴阳明。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200985,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '7、肺疟者。令人心寒。寒甚热。热间善惊。如有所见者。刺手太阴阳明。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bcpI0kCqB3r', 4, '{"title":"第20200986条・刺疟篇第三十六","description":"<p>8、心疟者。令人烦心甚。欲得清水。反寒多。不甚热。刺手少阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200986,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '8、心疟者。令人烦心甚。欲得清水。反寒多。不甚热。刺手少阴。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CXdHislR3G1', 4, '{"title":"第20200987条・刺疟篇第三十六","description":"<p>9、肝疟者。令人色苍苍然。太息。其状若死者。刺足厥阴见血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200987,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '9、肝疟者。令人色苍苍然。太息。其状若死者。刺足厥阴见血。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b8DOod28IDu', 4, '{"title":"第20200988条・刺疟篇第三十六","description":"<p>10、脾疟者。令人寒。腹中痛。热则肠中鸣。鸣已汗出。刺足太阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200988,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '10、脾疟者。令人寒。腹中痛。热则肠中鸣。鸣已汗出。刺足太阴。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l6GCrzvn1cC', 4, '{"title":"第20200989条・刺疟篇第三十六","description":"<p>11、肾疟者。令人洒洒然。腰脊痛宛转。大便难。目眴眴然。手足寒。刺足太阳少阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200989,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '11、肾疟者。令人洒洒然。腰脊痛宛转。大便难。目眴眴然。手足寒。刺足太阳少阴。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OsDGL3EZtrv', 4, '{"title":"第20200990条・刺疟篇第三十六","description":"<p>12、胃疟者。令人且病也。善饥而不能食。食而支满腹大。刺足阳明太阴横脉出血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200990,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '12、胃疟者。令人且病也。善饥而不能食。食而支满腹大。刺足阳明太阴横脉出血。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6Z36z14UNc6', 4, '{"title":"第20200991条・刺疟篇第三十六","description":"<p>13、疟发身方热。刺跗上动脉。开其空。出其血。立寒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200991,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '13、疟发身方热。刺跗上动脉。开其空。出其血。立寒。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zySDe1R2CAZ', 4, '{"title":"第20200992条・刺疟篇第三十六","description":"<p>14、疟方欲寒。刺手阳明太阴。足阳明太阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200992,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '14、疟方欲寒。刺手阳明太阴。足阳明太阴。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('msDKHdErUPA', 4, '{"title":"第20200993条・刺疟篇第三十六","description":"<p>15、疟脉满大。急刺背俞。用中针旁伍胠俞各一。适肥瘦出其血也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200993,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '15、疟脉满大。急刺背俞。用中针旁伍胠俞各一。适肥瘦出其血也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VGgfqG1X4jI', 4, '{"title":"第20200994条・刺疟篇第三十六","description":"<p>16、疟脉小实。急灸胫少阴。刺指井。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200994,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '16、疟脉小实。急灸胫少阴。刺指井。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0zNKMCjB3Pj');
