INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CiVeIkACf4x', 4, '{"title":"第20201035条・咳论篇第三十八","description":"<p>4、岐伯曰：皮毛者肺之合也。皮毛先受邪气。邪气以从其合也。其寒饮食入胃。从肺脉上至于肺则肺寒。肺寒则外内合邪因而客之。则为肺咳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201035,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '4、岐伯曰：皮毛者肺之合也。皮毛先受邪气。邪气以从其合也。其寒饮食入胃。从肺脉上至于肺则肺寒。肺寒则外内合邪因而客之。则为肺咳。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8v7ShqwuInO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qRX5KUNx17V', 4, '{"title":"第20201036条・咳论篇第三十八","description":"<p>5、五脏各以其时受病。非其时各传以与之。人与天地相参。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201036,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '5、五脏各以其时受病。非其时各传以与之。人与天地相参。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8v7ShqwuInO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VrOoXijedYF', 4, '{"title":"第20201037条・咳论篇第三十八","description":"<p>6、故五脏各以治时感于寒则受病。微则为咳。甚者为泄为痛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201037,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '6、故五脏各以治时感于寒则受病。微则为咳。甚者为泄为痛。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8v7ShqwuInO');
