INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EabYnsbnekp', 4, '{"title":"第20201047条・咳论篇第三十八","description":"<p>16、脾咳不已。则胃受之。胃咳之状。咳而呕。呕甚则长虫出。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201047,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '16、脾咳不已。则胃受之。胃咳之状。咳而呕。呕甚则长虫出。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8v7ShqwuInO');
