INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6ZnFKHGcRVa', 4, '{"title":"第20201050条・咳论篇第三十八","description":"<p>19、心咳不已。则小肠受之。小肠咳状。咳而失气。气与咳俱失。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201050,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '19、心咳不已。则小肠受之。小肠咳状。咳而失气。气与咳俱失。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8v7ShqwuInO');
