INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QgKhuj0dtqd', 4, '{"title":"第20201052条・咳论篇第三十八","description":"<p>21、久咳不已。则三焦受之。三焦咳状。咳而腹满。不欲食饮。此皆聚于胃。关于肺。使人多涕唾而面浮肿气逆也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201052,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '21、久咳不已。则三焦受之。三焦咳状。咳而腹满。不欲食饮。此皆聚于胃。关于肺。使人多涕唾而面浮肿气逆也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8v7ShqwuInO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kQRH62QeRCb', 4, '{"title":"第20201053条・咳论篇第三十八","description":"<p>22、帝曰：治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201053,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '22、帝曰：治之奈何？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8v7ShqwuInO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yzqDK212w51', 4, '{"title":"第20201054条・咳论篇第三十八","description":"<p>23、岐伯曰：治脏者治其俞。治腑者治其合。浮肿者治其经。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201054,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '23、岐伯曰：治脏者治其俞。治腑者治其合。浮肿者治其经。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8v7ShqwuInO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uT3nCSP85Jy', 4, '{"title":"第20201055条・咳论篇第三十八","description":"<p>24、帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201055,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '24、帝曰：善。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8v7ShqwuInO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IZRFBDyKqh4', 4, '{"title":"第20201056条・举痛论篇第三十九","description":"<p>1、黄帝问曰：余闻善言天者。必有验于人。善言古者。必有合于今。善言人者。必有厌于己。如此则道不惑而要数极。所谓明也。今余问于夫子。令言而可知。视而可见。扪而可得。令验于己而发蒙解惑。可得而闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201056,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '1、黄帝问曰：余闻善言天者。必有验于人。善言古者。必有合于今。善言人者。必有厌于己。如此则道不惑而要数极。所谓明也。今余问于夫子。令言而可知。视而可见。扪而可得。令验于己而发蒙解惑。可得而闻乎？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lRI6XlH3VKo', 4, '{"title":"第20201057条・举痛论篇第三十九","description":"<p>2、岐伯再拜稽首对曰：何道之问也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201057,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2、岐伯再拜稽首对曰：何道之问也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1qzJQ18OB2M', 4, '{"title":"第20201058条・举痛论篇第三十九","description":"<p>3、帝曰：愿闻人之五藏卒痛。何气使然？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201058,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '3、帝曰：愿闻人之五藏卒痛。何气使然？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jn8lq0fBRth', 4, '{"title":"第20201059条・举痛论篇第三十九","description":"<p>4、岐伯对曰：经脉流行不止。环周不休。寒气入经而稽迟。泣而不行。客于脉外则血少。客于脉中则气不通。故卒然而痛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201059,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '4、岐伯对曰：经脉流行不止。环周不休。寒气入经而稽迟。泣而不行。客于脉外则血少。客于脉中则气不通。故卒然而痛。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Mex4ZF5wLqJ', 4, '{"title":"第20201060条・举痛论篇第三十九","description":"<p>5、帝曰：其痛或卒然而止者。或痛甚不休者。或痛甚不可按者。或按之而痛止者。或按之无益者。或喘动应手者。或心与背相引而痛者。或胁肋与少腹相引而痛者。或腹痛引阴股者。或痛宿昔而成积者。或卒然痛死不知人有少间复生者。或痛而呕者。或腹痛而后泄者。或痛而闭不通者。凡此诸痛。各不同形。别之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201060,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '5、帝曰：其痛或卒然而止者。或痛甚不休者。或痛甚不可按者。或按之而痛止者。或按之无益者。或喘动应手者。或心与背相引而痛者。或胁肋与少腹相引而痛者。或腹痛引阴股者。或痛宿昔而成积者。或卒然痛死不知人有少间复生者。或痛而呕者。或腹痛而后泄者。或痛而闭不通者。凡此诸痛。各不同形。别之奈何？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Np7B3X4abOG', 4, '{"title":"第20201061条・举痛论篇第三十九","description":"<p>6、岐伯曰：寒气客于脉外则脉寒。脉寒则缩蜷。缩蜷则脉绌急。绌急则外引小络。故卒然而痛。得炅则痛立止。因重中于寒。则痛久矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201061,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '6、岐伯曰：寒气客于脉外则脉寒。脉寒则缩蜷。缩蜷则脉绌急。绌急则外引小络。故卒然而痛。得炅则痛立止。因重中于寒。则痛久矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XH05lVOm1YK', 4, '{"title":"第20201062条・举痛论篇第三十九","description":"<p>7、寒气客于经脉之中。与炅气相薄则脉满。满则痛而不可按也。寒气稽留。炅气从上。则脉充大而血气乱。故痛甚不可按也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201062,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '7、寒气客于经脉之中。与炅气相薄则脉满。满则痛而不可按也。寒气稽留。炅气从上。则脉充大而血气乱。故痛甚不可按也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rQupxkyXYpM', 4, '{"title":"第20201063条・举痛论篇第三十九","description":"<p>8、寒气客于肠胃之 间。膜原之下。血不得散。小络急引故痛。按之则血气散。故按之痛止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201063,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '8、寒气客于肠胃之 间。膜原之下。血不得散。小络急引故痛。按之则血气散。故按之痛止。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Fd20KhF241u', 4, '{"title":"第20201064条・举痛论篇第三十九","description":"<p>9、寒气客于侠脊之脉，则深按之不能及。故按之无益也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201064,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '9、寒气客于侠脊之脉，则深按之不能及。故按之无益也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3NORPaVNgdh', 4, '{"title":"第20201065条・举痛论篇第三十九","description":"<p>10、寒气客于冲脉。冲脉起于关元。随腹直上。寒气客则脉不通。脉不通则气因之。故喘动应手矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201065,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '10、寒气客于冲脉。冲脉起于关元。随腹直上。寒气客则脉不通。脉不通则气因之。故喘动应手矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EhnWK4M4q4I', 4, '{"title":"第20201066条・举痛论篇第三十九","description":"<p>11、寒气客于背俞之脉则脉泣。脉泣则血虚。血虚则痛。其俞注于心。故相引而痛。按之则热气至。热气至则痛止矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201066,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '11、寒气客于背俞之脉则脉泣。脉泣则血虚。血虚则痛。其俞注于心。故相引而痛。按之则热气至。热气至则痛止矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nMpYsotW0Ze', 4, '{"title":"第20201067条・举痛论篇第三十九","description":"<p>12、寒气客于厥阴之脉。厥阴之脉者。络阴器系于肝。寒气客于脉中。则血泣脉急。故胁肋与少腹相引痛矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201067,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '12、寒气客于厥阴之脉。厥阴之脉者。络阴器系于肝。寒气客于脉中。则血泣脉急。故胁肋与少腹相引痛矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MTUITE1PDkA', 4, '{"title":"第20201068条・举痛论篇第三十九","description":"<p>13、厥气客于阴股。寒气上及少腹。血泣在下相引。故腹痛引阴股。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201068,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '13、厥气客于阴股。寒气上及少腹。血泣在下相引。故腹痛引阴股。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K0oBsrPp3QK', 4, '{"title":"第20201069条・举痛论篇第三十九","description":"<p>14、寒气客于小肠膜原之间。络血之中。血泣不得注于大经。血气稽留不得行。故宿昔而成积矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201069,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '14、寒气客于小肠膜原之间。络血之中。血泣不得注于大经。血气稽留不得行。故宿昔而成积矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qWb4TcUoDYt', 4, '{"title":"第20201070条・举痛论篇第三十九","description":"<p>15、寒气客于五藏。厥逆上泄。阴气竭。阳气未入。故卒然痛死不知人。气复反则生矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201070,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '15、寒气客于五藏。厥逆上泄。阴气竭。阳气未入。故卒然痛死不知人。气复反则生矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xsCXyxJrvrX', 4, '{"title":"第20201071条・举痛论篇第三十九","description":"<p>16、寒气客于肠胃。厥逆上出。故痛而呕也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201071,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '16、寒气客于肠胃。厥逆上出。故痛而呕也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QPh3MbICjJw', 4, '{"title":"第20201072条・举痛论篇第三十九","description":"<p>17、寒气客于小肠。小肠不得成聚。故后泄腹痛矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201072,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '17、寒气客于小肠。小肠不得成聚。故后泄腹痛矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sEYEp07E7fI', 4, '{"title":"第20201073条・举痛论篇第三十九","description":"<p>18、热气留于小肠。肠中痛。瘅热焦渴则坚干不得出。故痛而闭不通矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201073,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '18、热气留于小肠。肠中痛。瘅热焦渴则坚干不得出。故痛而闭不通矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tcRREPUwc5L', 4, '{"title":"第20201074条・举痛论篇第三十九","description":"<p>19、帝曰：所谓言而可知者也。视而可见奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201074,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '19、帝曰：所谓言而可知者也。视而可见奈何？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2WzqrsXxaES', 4, '{"title":"第20201075条・举痛论篇第三十九","description":"<p>20、岐伯曰：五藏六腑固尽有部。视其五色。黄赤为热。白为寒。青黑为痛。此所谓视而可见者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201075,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '20、岐伯曰：五藏六腑固尽有部。视其五色。黄赤为热。白为寒。青黑为痛。此所谓视而可见者也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aS9Uxf6XRwv', 4, '{"title":"第20201076条・举痛论篇第三十九","description":"<p>21、帝曰：扪而可得。奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201076,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '21、帝曰：扪而可得。奈何？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tMeLSdmM2LO', 4, '{"title":"第20201077条・举痛论篇第三十九","description":"<p>22、岐伯曰：视其主病之脉。坚而血及陷下者。皆可扪而得也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201077,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '22、岐伯曰：视其主病之脉。坚而血及陷下者。皆可扪而得也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zek40a9SXP1', 4, '{"title":"第20201078条・举痛论篇第三十九","description":"<p>23、帝曰：善。余知百病生于气也。怒则气上。喜则气缓。悲则气消。恐则气下。寒则气收。炅则气泄。惊则气乱。劳则气耗。思则气结。九气不同。何病之生？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201078,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '23、帝曰：善。余知百病生于气也。怒则气上。喜则气缓。悲则气消。恐则气下。寒则气收。炅则气泄。惊则气乱。劳则气耗。思则气结。九气不同。何病之生？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1FhtR0RXQM6', 4, '{"title":"第20201079条・举痛论篇第三十九","description":"<p>24、岐伯曰：怒则气逆。甚则呕血及飧泄。故气上矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201079,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '24、岐伯曰：怒则气逆。甚则呕血及飧泄。故气上矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dMG1NL3HbPP', 4, '{"title":"第20201080条・举痛论篇第三十九","description":"<p>25、喜则气和志达。荣卫通利。故气缓矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201080,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '25、喜则气和志达。荣卫通利。故气缓矣。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '17WrFy479RY');
