INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dNI1Fi55xv7', 4, '{"title":"第20201103条・腹中论篇第四十","description":"<p>16、岐伯曰：此下则因阴。必下脓血。上则迫胃脘。生膈。挟胃脘内痈。此久病也。难治。居脐上为逆。居脐下为从。勿动亟夺。论在《刺法》中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201103,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '16、岐伯曰：此下则因阴。必下脓血。上则迫胃脘。生膈。挟胃脘内痈。此久病也。难治。居脐上为逆。居脐下为从。勿动亟夺。论在《刺法》中。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EYRSqpiQDMK', 4, '{"title":"第20201104条・腹中论篇第四十","description":"<p>17、帝曰：人有身体髀股䯒皆肿。环脐而痛。是为何病？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201104,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '17、帝曰：人有身体髀股䯒皆肿。环脐而痛。是为何病？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J6ykf4lnlhl', 4, '{"title":"第20201105条・腹中论篇第四十","description":"<p>18、岐伯曰：病名伏梁。此风根也。其气溢于大肠而着于肓。肓之原在脐下。故环脐而痛也。不可动之。动之为水溺涩之病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201105,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '18、岐伯曰：病名伏梁。此风根也。其气溢于大肠而着于肓。肓之原在脐下。故环脐而痛也。不可动之。动之为水溺涩之病。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('daXPgAEr4LN', 4, '{"title":"第20201106条・腹中论篇第四十","description":"<p>19、帝曰：夫子数言热中消中。不可服高梁芳草石药。石药发瘨。芳草发狂。夫热中消中者。皆富贵人也。今禁高梁。是不合其心。禁芳草石药。是病不愈。愿闻其说。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201106,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '19、帝曰：夫子数言热中消中。不可服高梁芳草石药。石药发瘨。芳草发狂。夫热中消中者。皆富贵人也。今禁高梁。是不合其心。禁芳草石药。是病不愈。愿闻其说。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dRmg8LZwgYk', 4, '{"title":"第20201107条・腹中论篇第四十","description":"<p>20、岐伯曰：夫芳草之气美。石药之气悍。二者其气急疾坚劲。故非缓心和人。不可以服此二者。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201107,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '20、岐伯曰：夫芳草之气美。石药之气悍。二者其气急疾坚劲。故非缓心和人。不可以服此二者。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Un17iA2JeUA', 4, '{"title":"第20201108条・腹中论篇第四十","description":"<p>21、帝曰：不可以服此二者。何以然？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201108,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '21、帝曰：不可以服此二者。何以然？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wUiUsGNzfO0', 4, '{"title":"第20201109条・腹中论篇第四十","description":"<p>22、岐伯曰：夫热气慓悍。药气亦然。二者相遇。恐内伤脾。脾者土也而恶木。服此药者。至甲乙日更论。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201109,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '22、岐伯曰：夫热气慓悍。药气亦然。二者相遇。恐内伤脾。脾者土也而恶木。服此药者。至甲乙日更论。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Frk1k6G1dK2', 4, '{"title":"第20201110条・腹中论篇第四十","description":"<p>23、帝曰：善。有病膺肿颈痛胸满腹胀。此为何病？何以得之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201110,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '23、帝曰：善。有病膺肿颈痛胸满腹胀。此为何病？何以得之？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Sujz9LT4y2c', 4, '{"title":"第20201111条・腹中论篇第四十","description":"<p>24、岐伯曰：名厥逆 。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201111,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '24、岐伯曰：名厥逆 。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
