INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iKW7D6QmVHF', 4, '{"title":"第20201113条・腹中论篇第四十","description":"<p>26、岐伯曰：灸之则喑。石之则狂。须其气并。乃可治也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201113,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '26、岐伯曰：灸之则喑。石之则狂。须其气并。乃可治也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
