INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MCZ76FNKDlL', 4, '{"title":"第20201115条・腹中论篇第四十","description":"<p>28、岐伯曰：阳气重上。有余于上。灸之则阳气入阴。入则喑。石之则阳气虚。虚则狂。须其气并而治之。可使全也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201115,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '28、岐伯曰：阳气重上。有余于上。灸之则阳气入阴。入则喑。石之则阳气虚。虚则狂。须其气并而治之。可使全也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AEQR6ejZYUN', 4, '{"title":"第20201116条・腹中论篇第四十","description":"<p>29、帝曰：善。何以知怀子之且生也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201116,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '29、帝曰：善。何以知怀子之且生也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5vhs1DFcT5n', 4, '{"title":"第20201117条・腹中论篇第四十","description":"<p>30、岐伯曰：身有病而无邪脉也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201117,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '30、岐伯曰：身有病而无邪脉也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oHsgHHUHQkZ', 4, '{"title":"第20201118条・腹中论篇第四十","description":"<p>31、帝曰：病热而有所痛者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201118,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '31、帝曰：病热而有所痛者何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Swc3rIyytbx', 4, '{"title":"第20201119条・腹中论篇第四十","description":"<p>32、岐伯曰：病热者。阳脉也。以三阳之动也。人迎一盛少阳。二盛太阳。三盛阳明。入阴也。夫阳入于阴。故病在头与腹。乃䐜胀而头痛也。帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201119,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '32、岐伯曰：病热者。阳脉也。以三阳之动也。人迎一盛少阳。二盛太阳。三盛阳明。入阴也。夫阳入于阴。故病在头与腹。乃䐜胀而头痛也。帝曰：善。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7PLdmEPN2I9');
